package br.com.rocardan.androws;

import android.app.*;
import android.os.*;
import android.content.*;
import android.content.pm.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.media.ToneGenerator;
import android.media.AudioManager;
import android.provider.Settings;
import android.view.*;
import android.view.animation.*;
import android.widget.*;
import android.text.*;
import java.text.*;
import java.util.*;

public class MainActivity extends Activity {
 final int[] colors={0xff0078d7,0xff00a4ef,0xff00aba9,0xff00a300,0xff60a917,0xffa4c400,0xfff0a30a,0xfffa6800,0xffe51400,0xffe671b8,0xfff472d0,0xffa200ff,0xff643ebf,0xff1ba1e2,0xff647687,0xff76608a,0xff6d8764,0xff825a2c,0xffa0522d,0xff000000};
 android.content.SharedPreferences prefs; LinearLayout base,content,tiles; TextView heading; int accent; boolean dark,modern,sounds; String screen="home";
 ArrayList<ResolveInfo> apps=new ArrayList<>(); PackageManager pm; final ArrayList<String> pinned=new ArrayList<>();
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK);prefs=getSharedPreferences("androws",0);pm=getPackageManager();accent=prefs.getInt("accent",colors[0]);dark=prefs.getBoolean("dark",true);modern=prefs.getBoolean("modern",false);sounds=prefs.getBoolean("sounds",true);loadApps();loadPins();showHome();}
 void loadApps(){Intent i=new Intent(Intent.ACTION_MAIN);i.addCategory(Intent.CATEGORY_LAUNCHER);apps.clear();apps.addAll(pm.queryIntentActivities(i,0));Collections.sort(apps,(a,b)->a.loadLabel(pm).toString().compareToIgnoreCase(b.loadLabel(pm).toString()));}
 void loadPins(){pinned.clear();String saved=prefs.getString("pins","");if(!saved.isEmpty())for(String s:saved.split("\\|"))if(!s.isEmpty())pinned.add(s);if(pinned.isEmpty()){for(String p:new String[]{"com.android.dialer","com.google.android.apps.messaging","com.android.chrome","com.android.camera2","com.google.android.gm","com.google.android.calendar"}){for(ResolveInfo a:apps)if(a.activityInfo.packageName.equals(p)){pinned.add(p);break;}}savePins();}}
 void savePins(){prefs.edit().putString("pins",android.text.TextUtils.join("|",pinned)).apply();}
 int fg(){return dark?Color.WHITE:Color.BLACK;} int bg(){return dark?Color.BLACK:Color.WHITE;}
 GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 TextView text(String s,int sp,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(fg());t.setTextSize(sp);if(bold)t.setTypeface(Typeface.create("sans-serif-light",Typeface.BOLD));return t;}
 void sound(){if(sounds)try{new ToneGenerator(AudioManager.STREAM_SYSTEM,30).startTone(ToneGenerator.TONE_PROP_BEEP,45);}catch(Exception ignored){}}
 void root(String name){screen=name;base=new LinearLayout(this);base.setOrientation(1);base.setBackgroundColor(bg());setContentView(base);content=new LinearLayout(this);content.setOrientation(1);base.addView(content,new LinearLayout.LayoutParams(-1,-1));}
 void header(String title,String right,Runnable action){LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);h.setPadding(dp(18),dp(18),dp(14),dp(12));TextView t=text(title,32,false);h.addView(t,new LinearLayout.LayoutParams(0,-2,1));TextView b=text(right,24,false);b.setPadding(dp(12),0,dp(10),0);h.addView(b);b.setOnClickListener(v->{sound();action.run();});content.addView(h);}
 void showHome(){root("home");header("início","→",()->showApps("") );ScrollView sc=new ScrollView(this);content.addView(sc);tiles=new LinearLayout(this);tiles.setPadding(dp(8),0,dp(8),dp(28));tiles.setOrientation(1);sc.addView(tiles);TextView clock=text(new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date()),46,false);clock.setPadding(dp(12),dp(5),0,dp(10));tiles.addView(clock);TextView date=text(new SimpleDateFormat("EEEE, d MMMM",new Locale("pt","BR")).format(new Date()),18,false);date.setPadding(dp(12),0,0,dp(15));tiles.addView(date);
  int i=0;while(i<pinned.size()){LinearLayout row=new LinearLayout(this);tiles.addView(row);for(int j=0;j<2 && i<pinned.size();j++,i++){String pkg=pinned.get(i);ResolveInfo a=find(pkg);String name=a==null?pkg:a.loadLabel(pm).toString();LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);tile.setGravity(Gravity.CENTER);tile.setPadding(dp(8),dp(8),dp(8),dp(8));tile.setBackground(shape(accent,modern?0:1));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(prefs.getInt("size_"+pkg,1)==2?190:145),1);lp.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(tile,lp);if(a!=null){ImageView iv=new ImageView(this);iv.setImageDrawable(a.loadIcon(pm));tile.addView(iv,new LinearLayout.LayoutParams(dp(54),dp(54)));}TextView label=text(name,16,true);label.setGravity(Gravity.CENTER);label.setMaxLines(2);label.setPadding(0,dp(10),0,0);label.setTextColor(Color.WHITE);tile.addView(label);tile.setOnClickListener(v->launch(pkg));tile.setOnLongClickListener(v->{tileMenu(pkg);return true;});}}
  TextView hint=text("Segure um bloco para editar  •  Deslize para ver os apps",12,false);hint.setGravity(Gravity.CENTER);hint.setPadding(0,dp(18),0,dp(10));tiles.addView(hint);TextView settings=text("⚙  Configurações     ◷  Tela de bloqueio",17,false);settings.setGravity(Gravity.CENTER);settings.setPadding(0,dp(20),0,dp(20));tiles.addView(settings);settings.setOnClickListener(v->showSettings());settings.setOnLongClickListener(v->{showLock();return true;});
  sc.setOnTouchListener(new View.OnTouchListener(){float x,y;public boolean onTouch(View v,android.view.MotionEvent e){if(e.getAction()==0){x=e.getX();y=e.getY();}if(e.getAction()==1&&x-e.getX()>dp(100)&&Math.abs(y-e.getY())<dp(100)){showApps("");return true;}return false;}});
 }
 ResolveInfo find(String pkg){for(ResolveInfo a:apps)if(a.activityInfo.packageName.equals(pkg))return a;return null;}
 void launch(String pkg){ResolveInfo a=find(pkg);if(a==null){Toast.makeText(this,"Aplicativo não encontrado",Toast.LENGTH_SHORT).show();return;}sound();try{Intent intent=new Intent(Intent.ACTION_MAIN);intent.addCategory(Intent.CATEGORY_LAUNCHER);intent.setClassName(a.activityInfo.packageName,a.activityInfo.name);intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(intent);overridePendingTransition(android.R.anim.fade_in,android.R.anim.fade_out);}catch(Exception ex){Toast.makeText(this,"Não foi possível abrir",Toast.LENGTH_SHORT).show();}}
 void tileMenu(String pkg){String[] opts={"Abrir","Mover para cima","Mover para baixo","Tamanho pequeno","Tamanho grande","Desafixar"};new AlertDialog.Builder(this).setTitle("Editar bloco").setItems(opts,(d,n)->{int idx=pinned.indexOf(pkg);switch(n){case 0:launch(pkg);return;case 1:if(idx>0)Collections.swap(pinned,idx,idx-1);break;case 2:if(idx<pinned.size()-1)Collections.swap(pinned,idx,idx+1);break;case 3:prefs.edit().putInt("size_"+pkg,1).apply();break;case 4:prefs.edit().putInt("size_"+pkg,2).apply();break;case 5:pinned.remove(pkg);break;}savePins();showHome();}).show();}
 void showApps(String filter){root("apps");header("aplicativos","⌂",()->showHome());EditText search=new EditText(this);search.setSingleLine(true);search.setHint("Pesquisar aplicativos");search.setTextColor(fg());search.setHintTextColor(0xff888888);search.setPadding(dp(20),dp(10),dp(20),dp(15));content.addView(search);ScrollView scroll=new ScrollView(this);content.addView(scroll);LinearLayout list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);populate(list,filter);search.setText(filter);search.setSelection(filter.length());search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){populate(list,s.toString());}public void afterTextChanged(Editable e){}});}
 void populate(LinearLayout list,String query){list.removeAllViews();String prev="";for(ResolveInfo a:apps){String name=a.loadLabel(pm).toString();if(!name.toLowerCase().contains(query.toLowerCase()))continue;String letter=name.substring(0,1).toUpperCase();if(query.isEmpty()&&!letter.equals(prev)){TextView l=text(letter,26,true);l.setTextColor(accent);l.setPadding(dp(20),dp(12),0,dp(8));list.addView(l);prev=letter;}LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(20),dp(9),dp(10),dp(9));ImageView icon=new ImageView(this);icon.setImageDrawable(a.loadIcon(pm));row.addView(icon,new LinearLayout.LayoutParams(dp(38),dp(38)));TextView t=text(name,19,false);t.setPadding(dp(16),0,0,0);row.addView(t);list.addView(row);String pkg=a.activityInfo.packageName;row.setOnClickListener(v->launch(pkg));row.setOnLongClickListener(v->{new AlertDialog.Builder(this).setItems(new String[]{pinned.contains(pkg)?"Desafixar da tela inicial":"Fixar na tela inicial","Abrir"},(d,n)->{if(n==0){if(pinned.contains(pkg))pinned.remove(pkg);else pinned.add(pkg);savePins();Toast.makeText(this,"Blocos atualizados",Toast.LENGTH_SHORT).show();}else launch(pkg);}).show();return true;});}}
 void showSettings(){root("settings");header("configurações","⌂",()->showHome());ScrollView sc=new ScrollView(this);content.addView(sc);LinearLayout body=new LinearLayout(this);body.setPadding(dp(18),dp(8),dp(18),dp(30));body.setOrientation(1);sc.addView(body);setting(body,"Estilo visual",modern?"Windows 10 Mobile":"Windows Phone 8.1",()->new AlertDialog.Builder(this).setItems(new String[]{"Windows Phone 8.1","Windows 10 Mobile"},(d,n)->{modern=n==1;prefs.edit().putBoolean("modern",modern).apply();showSettings();}).show());setting(body,"Aparência",dark?"Escuro":"Claro",()->{dark=!dark;prefs.edit().putBoolean("dark",dark).apply();showSettings();});setting(body,"Cor de destaque","Escolher entre 20 cores",()->chooseColor());setting(body,"Sons da interface",sounds?"Ativados":"Desativados",()->{sounds=!sounds;prefs.edit().putBoolean("sounds",sounds).apply();showSettings();});setting(body,"Notificações","Autorizar leitura de notificações",()->startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS")));setting(body,"Launcher padrão","Selecionar Androws como tela inicial",()->{try{startActivity(new Intent(Settings.ACTION_HOME_SETTINGS));}catch(Exception e){Toast.makeText(this,"Abra Configurações > Apps padrão > Tela inicial",Toast.LENGTH_LONG).show();}});setting(body,"Tela de bloqueio","Prévia da tela Metro",()->showLock());setting(body,"Sobre","ANDROWS 1.0 • ROCARDAN SYSTEMS",()->new AlertDialog.Builder(this).setTitle("ANDROWS 1.0").setMessage("Desenvolvido por ROCARDAN SYSTEMS\nInspirado no Windows Phone 8.1 e Windows 10 Mobile.\n\nLauncher independente para Android 15+").setPositiveButton("OK",null).show());}
 void setting(LinearLayout body,String name,String desc,Runnable action){LinearLayout block=new LinearLayout(this);block.setOrientation(1);block.setPadding(dp(10),dp(14),dp(8),dp(16));TextView title=text(name,21,false);block.addView(title);TextView sub=text(desc,14,false);sub.setTextColor(0xff888888);block.addView(sub);body.addView(block);View line=new View(this);line.setBackgroundColor(dark?0xff333333:0xffdddddd);body.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));block.setOnClickListener(v->{sound();action.run();});}
 void chooseColor(){ScrollView sc=new ScrollView(this);LinearLayout all=new LinearLayout(this);all.setOrientation(1);sc.addView(all);for(int r=0;r<5;r++){LinearLayout row=new LinearLayout(this);all.addView(row);for(int c=0;c<4;c++){final int value=colors[r*4+c];TextView tile=text("■",40,true);tile.setTextColor(value);tile.setGravity(Gravity.CENTER);row.addView(tile,new LinearLayout.LayoutParams(0,dp(72),1));tile.setOnClickListener(v->{accent=value;prefs.edit().putInt("accent",accent).apply();showSettings();});}}new AlertDialog.Builder(this).setTitle("Cores Metro").setView(sc).setNegativeButton("Fechar",null).show();}
 void showLock(){root("lock");content.setBackgroundColor(accent);content.setGravity(Gravity.CENTER);TextView time=text(new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date()),74,false);time.setTextColor(Color.WHITE);time.setGravity(Gravity.CENTER);content.addView(time);TextView date=text(new SimpleDateFormat("EEEE, d 'de' MMMM",new Locale("pt","BR")).format(new Date()),22,false);date.setTextColor(Color.WHITE);date.setGravity(Gravity.CENTER);content.addView(date);TextView note=text("Prévia da tela de bloqueio\n\nToque para desbloquear",16,false);note.setTextColor(Color.WHITE);note.setGravity(Gravity.CENTER);note.setPadding(0,dp(65),0,0);content.addView(note);content.setOnClickListener(v->showHome());}
 @Override public void onBackPressed(){if(screen.equals("home"))super.onBackPressed();else showHome();}
}
